#!/usr/bin/env python3
"""Раздел 2 «Проектирование и конструирование программного средства».
Основа оформления: docs/kursovaya/src/er-part.docx (как в build_14/build_15).
Использование: python3 build_2.py выход.docx
"""
import os, sys
import docx
from docx.oxml import parse_xml
from docx.oxml.ns import qn
from docx.shared import Cm
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Builder, polish

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
KURS = os.path.join(ROOT, 'docs', 'kursovaya')

M = 'xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math"'


def mr(t):
    """Текст в формуле."""
    return f'<m:r><m:t xml:space="preserve">{t}</m:t></m:r>'


def frac(num, den):
    return f'<m:f><m:num>{num}</m:num><m:den>{den}</m:den></m:f>'


def sup(base, s):
    return f'<m:sSup><m:e>{base}</m:e><m:sup>{s}</m:sup></m:sSup>'


def sub(base, s):
    return f'<m:sSub><m:e>{base}</m:e><m:sub>{s}</m:sub></m:sSub>'


def formula(b, omml, number):
    """Формула по центру строки, номер в скобках у правого поля (СТП)."""
    p = b.para('', 'body')
    pf = p.paragraph_format
    pf.first_line_indent = Cm(0)
    tabs = parse_xml(
        '<w:tabs xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">'
        '<w:tab w:val="center" w:pos="4648"/><w:tab w:val="right" w:pos="9355"/></w:tabs>')
    p._p.get_or_add_pPr().append(tabs)
    p.add_run().add_tab()
    p._p.append(parse_xml(f'<m:oMath {M}>{omml}</m:oMath>'))
    r = p.add_run()
    r.add_tab()
    r.add_text(f'({number})')
    r.font.name = 'Times New Roman'
    r.font.size = b.fmt['body']['size']
    return p


def build(out):
    d = docx.Document(os.path.join(KURS, 'src', 'er-part.docx'))
    P = d.paragraphs
    b = Builder(d, P[1], P[4], P[6])
    body = d.element.body
    for el in list(body):
        if not el.tag.endswith('sectPr'):
            body.remove(el)

    fig = os.path.join(KURS, '%s.png').__mod__

    b.heading('2 ПРОЕКТИРОВАНИЕ И КОНСТРУИРОВАНИЕ ПРОГРАММНОГО СРЕДСТВА')

    # 2.1 ------------------------------------------------------------------
    b.heading('2.1 Постановка задачи')
    b.para('Целью разработки является программное средство дистанционного банковского обслуживания физических лиц: веб-приложение, через которое клиент управляет своими счетами и банковскими продуктами, а сотрудники банка выполняют операционную работу. Приложение работает в браузере без установки на компьютер пользователя и обслуживает четыре категории пользователей: гостя, клиента, сотрудников банка (операционист, кредитный специалист, специалист по финансовому мониторингу) и администратора.')
    b.para('Программное средство должно обеспечивать выполнение следующих операций:')
    for item in [
        '– регистрацию клиента с проверкой анкеты операционистом и открытием первого текущего счёта;',
        '– открытие и закрытие счетов в пяти валютах с номером в формате IBAN;',
        '– переводы между своими счетами с конвертацией, переводы другим клиентам банка и в другие банки через клиринг, с суточным лимитом и подтверждением одноразовым кодом;',
        '– оплату услуг по каталогу, шаблоны платежей и автоплатежи;',
        '– оформление вкладов с расчётом дохода, начисление процентов при закрытии операционного дня и досрочное закрытие с перерасчётом;',
        '– выдачу кредитов: скоринг заявки, график платежей (аннуитетный или дифференцированный), плановое списание платежей, пеню при просрочке, досрочное погашение;',
        '– выпуск, блокировку и закрытие платёжных карт, лимиты и покупки;',
        '– выписку по счёту, справку об остатке и квитанции в формате PDF;',
        '– контроль подозрительных переводов с задержкой операции до решения специалиста;',
        '– администрирование: курсы и тарифы, пользователи и роли, журнал аудита, отчёты, резервное копирование и закрытие операционного дня.'
    ]:
        b.para(item)
    b.para('Входными данными являются анкеты клиентов, реквизиты операций, вводимые в формах, курсы валют Национального банка и настройки тарифов. Выходными данными являются проводки и документы в базе данных, ответы программного интерфейса в формате JSON, уведомления пользователям, документы PDF и отчёты. Все денежные суммы хранятся и обрабатываются в копейках целыми числами, операции датируются банковской датой, которую сдвигает только закрытие операционного дня. Интерфейс выполняется на русском языке и должен работать в браузерах Яндекс Браузер, Firefox, Chrome и Opera в среде Windows 10 и новее.')

    # 2.2 ------------------------------------------------------------------
    b.heading('2.2 Обоснование выбора технологий разработки')
    b.para('Серверная часть выполнена на платформе Node.js 22 с каркасом Express 5. Выбор определяется требованием задания вести бизнес-логику на языке JavaScript: платформа Node.js позволяет использовать один язык и одни и те же приёмы на сервере и на клиенте, что упрощает сопровождение учебного проекта одним разработчиком. Событийная модель Node.js хорошо подходит для нагрузки интернет-банка, состоящей из множества коротких запросов к базе данных. Каркас Express выбран как минималистичный и самый распространённый для Node.js: он даёт маршрутизацию и цепочку промежуточных обработчиков, не навязывая структуру приложения, поэтому слои приложения удалось организовать по собственным правилам. Статическая типизация обеспечивается аннотациями JSDoc, которые проверяются редактором без компиляции и не нарушают требование использовать именно JavaScript, а не TypeScript.')
    b.para('В качестве СУБД используется MySQL 8 с подсистемой хранения InnoDB. Для банковской предметной области определяющими являются транзакции, блокировки на уровне строк и ссылочная целостность: каждая денежная операция выполняется в одной транзакции с уровнем изоляции READ COMMITTED и явными блокировками SELECT FOR UPDATE, внешние ключи защищают связи между счетами, документами и проводками, а триггеры запрещают изменение и удаление строк журнала аудита и проводок. Схема базы данных ведётся в виде пронумерованных SQL-файлов без ORM: тот же набор файлов служит листингом SQL-скрипта создания базы в приложении к записке. Доступ к базе выполняет драйвер mysql2 с параметризованными запросами.')
    b.para('Клиентская часть построена на HTML5, CSS3 и JavaScript без каркасов и шаблонизаторов. Интерфейс собирается в браузере модулями JavaScript: сервер отдаёт статические файлы и данные в формате JSON, переходы между страницами выполняет собственный маршрутизатор на основе History API. Такое решение удовлетворяет требованию единой каскадной таблицы стилей на всё приложение, не требует сборщика и прозрачно показывает владение базовыми веб-технологиями. Из внешних библиотек на сервере применяются: express-session для сессий, bcrypt для хэширования паролей, helmet для защитных HTTP-заголовков, express-rate-limit для ограничения частоты запросов, nodemailer для отправки писем, pdfkit для документов PDF, qrcode для QR-кода настройки двухфакторной защиты. Автоматические тесты выполняются средствами Vitest и supertest на отдельной тестовой базе данных.')

    # 2.3 ------------------------------------------------------------------
    b.heading('2.3 Архитектурные решения')
    b.para('Приложение имеет клиент-серверную архитектуру. Сервер предоставляет программный интерфейс по адресам /api и статические файлы интерфейса; любой другой адрес получает страницу-оболочку, внутри которой клиентский маршрутизатор сам выбирает страницу. Серверный код организован по предметным модулям: счета, переводы, платежи, вклады, кредиты, карты, антифрод, клиенты, уведомления, администрирование и другие. Каждый модуль состоит из четырёх слоёв, выстроенных по шаблону проектирования MVC.')
    b.para('Путь запроса через слои модуля показан на рисунке 2.1 на примере перевода.')
    b.figure(fig('fig-arch'), 'Рисунок 2.1 – Слои обработки запроса на примере модуля переводов')
    b.para('Запрос из браузера проходит общие промежуточные обработчики: загрузку сессии, проверку токена CSRF, загрузку пользователя с правами его роли и контроль обязательной двухфакторной защиты сотрудников. Маршрут связывает адрес и метод HTTP с обработчиком и проверяет право доступа, причём проверяется код права, а не название роли: набор прав закреплён за ролью в базе данных. Контроллер разбирает параметры запроса и формирует ответ JSON, не содержа бизнес-логики. Сервис реализует бизнес-правила и управляет транзакциями, модель выполняет SQL-запросы с параметрами-плейсхолдерами. Правило зависимостей одностороннее: контроллеры не пишут SQL, модели не знают про HTTP, поэтому бизнес-логику можно проверять автотестами без веб-слоя.')
    b.para('Денежное ядро построено на принципе двойной записи. Каждая денежная операция оформляется документом с набором проводок «дебет – кредит – сумма», остаток счёта равен обороту по кредиту за вычетом оборота по дебету и хранится как итог, который сверяется с проводками. Сервис двойной записи выполняет проводки документа в одной транзакции: блокирует задействованные счета в порядке возрастания идентификаторов, что исключает взаимные блокировки, проверяет статусы счетов и достаточность средств с учётом зарезервированных сумм и отклоняет документ целиком при любой ошибке. Ключ идемпотентности защищает от повторного проведения при двойной отправке формы: повторный запрос возвращает уже созданный документ. Исправления выполняются только сторнированием: проводки ошибочного документа повторяются с обратным знаком, история не переписывается.')
    b.para('Операционное время системы задаёт банковская дата. Её сдвигает процедура закрытия операционного дня, которая последовательно начисляет проценты и закрывает вклады с наступившим сроком, списывает платежи по кредитам и начисляет пеню, выполняет автоплатежи, отправляет пакет клиринга в другие банки и завершается контролем оборотно-сальдовой ведомости: в каждой валюте сумма остатков всех счетов должна быть нулевой. Каждая операция дня выполняется во вложенной точке сохранения, поэтому ошибка одного платежа не откатывает закрытие дня целиком. Сессии пользователей хранятся в таблице базы данных, фоновые задачи сервера ограничиваются отправкой писем из очереди и резервным копированием по расписанию.')

    # 2.4 ------------------------------------------------------------------
    b.heading('2.4 Алгоритмы бизнес-логики')
    b.para('Наиболее нагруженный проверками алгоритм – перевод клиенту банка: в нём участвуют контроль данных, суточный лимит, правила антифрода, подтверждение одноразовым кодом и проводки двойной записи. Схема алгоритма приведена на рисунке 2.2.')
    b.figure(fig('fig-flow'), 'Рисунок 2.2 – Схема алгоритма перевода клиенту банка', width=10.2)
    b.para('Алгоритм начинается с проверки данных: счёт списания должен принадлежать клиенту и быть открытым, номер счёта получателя проверяется по контрольным цифрам IBAN и ищется в банке, сумма должна быть положительной. Сумма пересчитывается в белорусские рубли по официальному курсу и сверяется с суточным лимитом клиента, в который входят переводы другим клиентам и в другие банки за банковскую дату. Затем вычисляется оценка риска: правила антифрода начисляют баллы за крупную сумму, первый перевод новому получателю, частые переводы за короткое время и крупный перевод нового клиента. Если сумма баллов достигает порога проверки, перевод задерживается: сумма резервируется на счёте, случай попадает в очередь специалиста по финансовому мониторингу, и алгоритм завершается до его решения. Если требуется подтверждение (сумма не ниже порога либо баллы не ниже порога подтверждения), клиенту отправляется одноразовый код, на ввод которого даётся пять минут и три попытки. Завершает алгоритм транзакция: строки счетов блокируются, лимит и остаток проверяются повторно уже под блокировкой, выполняются проводки перевода и комиссии. Такая повторная проверка закрывает гонку двух одновременно подтверждаемых заявок, созданных до исчерпания лимита.')
    b.para('График платежей по кредиту строится двумя способами. Аннуитетный ежемесячный платёж вычисляется по формуле (2.1):')
    i = mr('i'); n = mr('n'); one = mr('1')
    formula(b, mr('A=') + frac(mr('S') + mr('·') + i, one + mr('−') + sup(mr('(') + one + mr('+') + i + mr(')'), mr('−') + n)), '2.1')
    b.para('где S – сумма кредита; i – месячная ставка, равная годовой ставке, делённой на 12 и на 100; n – срок кредита в месяцах. Проценты каждого платежа начисляются на остаток долга, погашение долга равно разности аннуитета и процентов, последний платёж закрывает остаток полностью с поправкой на округления.')
    b.para('При дифференцированном графике долг гасится равными долями, а платёж убывает; платёж с номером k вычисляется по формуле (2.2):')
    formula(b, sub(mr('A'), mr('k')) + mr('=') + frac(mr('S'), n) + mr('+') + sub(mr('O'), mr('k−1')) + mr('·') + i, '2.2')
    b.para('где O с индексом k−1 – остаток долга перед платежом. Все вычисления ведутся в копейках с округлением до ближайшей копейки, половина копейки округляется вверх.')
    b.para('Проценты по вкладу начисляются за фактическое число дней по формуле (2.3):')
    formula(b, mr('I=') + frac(mr('B') + mr('·') + mr('r') + mr('·') + mr('d'), mr('100') + mr('·') + mr('D')), '2.3')
    b.para('где B – база начисления (остаток вклада); r – годовая ставка в процентах; d – число дней периода; D – число дней в году (365 или 366). Период, захватывающий границу лет, считается по частям для каждого года. При капитализации проценты прибавляются к вкладу и входят в базу следующего периода, иначе выплачиваются на текущий счёт. При досрочном закрытии доход пересчитывается по ставке до востребования, излишне выплаченные проценты удерживаются из возвращаемой суммы.')
    b.para('Пеня по просроченному платежу кредита начисляется за каждый день просрочки по формуле (2.4):')
    formula(b, mr('P=') + frac(sub(mr('S'), mr('пр')) + mr('·') + mr('p') + mr('·') + mr('d'), mr('100')), '2.4')
    b.para('где S с индексом «пр» – сумма просроченного платежа (долг и проценты); p – ставка пени за день, по умолчанию 0,1 %; d – число дней просрочки. Платежи при закрытии дня списываются строго по порядку графика: пока не оплачен ранний платёж, более поздние не списываются.')
    b.para('Скоринг кредитной заявки выполняет модель логистической регрессии, обученная на истории выдач. Вероятность дефолта вычисляется по формулам (2.5) и (2.6):')
    formula(b, mr('PD=') + frac(one, one + sup(mr('e'), mr('−z'))), '2.5')
    formula(b, mr('z=') + sub(mr('w'), mr('0')) + mr('+') + sub(mr('w'), one) + sub(mr('x'), one) + mr('+…+') + sub(mr('w'), mr('m')) + sub(mr('x'), mr('m')), '2.6')
    b.para('где x – нормированные признаки заявки (возраст, доход, обязательства, отношение платежа к доходу, стаж, число иждивенцев, сумма); w – веса, подобранные градиентным спуском. Решение принимается по порогам: при вероятности дефолта не выше 8 % и сумме в пределах лимита заявка одобряется автоматически, при вероятности до 30 % направляется кредитному специалисту, выше – отклоняется. Независимо от скоринга заявка отклоняется, если долговая нагрузка (отношение ежемесячных платежей к доходу) превышает 40 %. Если обученной модели нет, действует балльная карта с теми же признаками.')

    # 2.5 ------------------------------------------------------------------
    b.heading('2.5 Проектирование пользовательского интерфейса')
    b.para('Интерфейс спроектирован по макетам, подготовленным до вёрстки, и опирается на приёмы действующих банковских сайтов: светлая страница, крупные скруглённые плитки разделов, двухэтажная шапка с утилитарной полосой и меню, чипы-переключатели и талоны-квитанции для результатов операций. Все стили собраны в единственной каскадной таблице, встроенные стили запрещены политикой безопасности содержимого и проверяются автотестом. Цвета заданы переменными CSS: палитра переключается классом на корневом элементе, тёмная тема переопределяет переменные и включается переключателем в шапке либо по системной настройке, выбор запоминается в браузере. Основной шрифт – Golos Text с табличными цифрами, чтобы суммы в колонках выравнивались по разрядам.')
    b.para('Главная страница кабинета клиента показана на рисунке 2.3. Вверху кабинета выводятся сумма по счетам в национальной валюте, кнопки частых действий и напоминание о ближайшем платеже по кредиту, ниже – четыре плитки продуктов с объёмными значками, последние операции и курсы. Каждая страница приложения является модулем JavaScript, который запрашивает данные программного интерфейса и возвращает разметку; разметка собирается шаблонной функцией с автоматическим экранированием подстановок, что исключает внедрение разметки через данные. Маршрутизатор перехватывает переходы по ссылкам, обновляет содержимое без перезагрузки страницы и после перехода переводит фокус на содержимое, чтобы программы чтения с экрана объявляли новую страницу.')
    b.figure(fig('fig-ui-cabinet'), 'Рисунок 2.3 – Главная страница кабинета клиента', width=15.2)
    b.para('Каталог оплаты услуг показан на рисунке 2.4. Категории каталога оформлены крупными плитками с объёмными значками в едином фирменном стиле: серебристый металл с оранжевым свечением, сами значки сгенерированы по единому описанию стиля и хранятся с прозрачным фоном. Формы приложения подключаются общим помощником: он блокирует повторную отправку, показывает ошибки сервера у конкретных полей, а для необратимых действий (закрыть счёт, закрыть карту, удалить шаблон, закрыть операционный день) требует подтверждения прямо в форме.')
    b.figure(fig('fig-ui-catalog'), 'Рисунок 2.4 – Каталог оплаты услуг', width=15.2)
    b.para('Анимации ограничены случаями, когда они сообщают о состоянии: полоса загрузки, появление блоков, счётчик суммы; при включённой в системе настройке уменьшения движения анимации отключаются. Вёрстка адаптируется к ширине телефона без горизонтальной прокрутки, интерфейс остаётся работоспособным при отключённых анимациях и увеличенном масштабе шрифта.')

    # 2.6 ------------------------------------------------------------------
    b.heading('2.6 Методы обеспечения безопасности данных')
    b.para('Пароли пользователей хранятся только в виде хэшей bcrypt с коэффициентом стоимости 12. Попытки входа ограничены: после пяти неудач учётная запись блокируется на 15 минут, счётчик сбрасывается только после полностью завершённого входа, включая второй фактор, поэтому верный пароль не открывает перебор кодов. Частота запросов входа и регистрации ограничена по адресу клиента, а адрес из заголовков прокси принимается только при явной настройке доверенного прокси.')
    b.para('Сессия создаётся на сервере и передаётся браузеру в cookie с флагами httpOnly и SameSite; при входе идентификатор сессии и токен CSRF выпускаются заново. Сессия завершается после 30 минут бездействия и в любом случае через восемь часов после входа. Все запросы, меняющие данные, проверяют токен CSRF из заголовка, сравнение выполняется за постоянное время. Двухфакторная защита реализована по стандарту TOTP (RFC 6238): шестизначный код сменяется каждые 30 секунд, допускается расхождение часов на два шага, каждый код принимается один раз, при настройке выдаются десять одноразовых резервных кодов. Для сотрудников банка двухфакторная защита обязательна, включение защиты требует повторного ввода пароля.')
    b.para('Персональные данные клиента – серия и номер паспорта, идентификационный номер, секрет TOTP – шифруются алгоритмом AES-256-GCM с проверкой подлинности шифртекста; для поиска дубликатов хранится отдельный ключевой хэш HMAC-SHA-256. Операции с деньгами дополнительно подтверждаются одноразовым кодом со сроком действия пять минут и тремя попытками ввода, счётчик попыток изменяется в транзакции, поэтому параллельные запросы не дают дополнительных попыток. Входные данные проверяются на сервере: числовые идентификаторы, допустимые значения справочников, длины строк под размеры столбцов; специальные символы поиска экранируются.')
    b.para('Все значимые действия записываются в журнал аудита: кто, когда, с какого адреса и с каким результатом выполнил действие. Триггеры базы данных запрещают изменение и удаление строк журнала и проводок, поэтому история не может быть переписана даже администратором. Резервная копия базы создаётся по расписанию утилитой mysqldump и сразу шифруется ключом приложения; восстановление сохраняет записи журнала аудита, сделанные после создания копии, и завершает все сеансы пользователей. Защитные HTTP-заголовки, включая политику безопасности содержимого, выставляет промежуточный обработчик helmet: загрузка скриптов и стилей разрешена только с собственного адреса приложения.')
    b.para('Принятые решения покрывают требования задания к безопасности: шифрование хранимых и передаваемых данных, разграничение прав по ролям, контроль целостности операций и резервное копирование, и при этом проверяются автоматическими тестами вместе с остальной бизнес-логикой.')

    d.save(out)
    polish(out)


